# Cultural-bias condition independently supported by AQA culture guidance.
traps={80:'Do not assume that restrictions have only benefits or only drawbacks.',64:'Do not assume research automatically determines government policy.',39:'Do not collect identifiable responses without explaining how privacy is protected.',67:'Do not assume that intensified attention proves the original threat was objectively large.',71:'Do not assume a victim survey captures every type of offence.',59:'Do not treat statistical significance as proof of a large or causal effect.',3:'Do not use a leading question that assumes peer pressure occurred.',9:'Do not call the task realistic merely because it is controlled.',14:'Do not name a change without explaining its effect on data quality.',22:'Do not call a claim scientific if no possible result could contradict it.',54:'Do not put the procedural detail only in the discussion section.',16:'Do not choose a correlation test for categorical frequency data.',26:'Do not leave all participants in the same condition order.',34:'Do not infer causation from a positive correlation.',79:'Do not assume a functionalist explanation rules out religious conflict.',81:'Do not assume religious visibility proves religious participation is increasing everywhere.',37:'Do not mistake accuracy of a single observer for agreement between observers.',41:'Do not assume counts remain qualitative just because they came from interviews.',82:'Do not describe each theory separately without comparing how they explain the same issue.',36:'Do not describe the zone of proximal development as a task already mastered alone.',0:'Do not confuse a false positive with a Type II error.',2:'Do not treat the two experimental conditions as bars in a histogram.',1:'Do not treat a convenient sample as representative of the whole sixth form.',5:'Do not infer causation from a correlation.',25:'Do not divide by N−1 when the question specifies the population procedure.',30:'Do not use 18 as the denominator.',31:'Do not substitute a memorised topic summary for an argument answering the question.',35:'Do not use the largest score as the range.',43:'Do not choose an unrelated test for the same participants.',62:'Do not divide the frequency for B by the number of categories.',63:'Do not assume that a partial explanation secures informed consent.'}
kept=[]; quarantine=[]
for i,c in enumerate(x):
 for k in ('front','stable_key','catalogue_card_id','catalogue_id'): assert c[k]==orig[i][k]
 c['tags']=[t for t in c['tags'] if not (t.startswith('PPP::Spec::') or t in ('PPP::Class::direct','PPP::Class::support') or re.match(r'AQA_(?:PSYCH|SOC)_',t))]
 if i in verified:
  if not c['back'].startswith('<p><strong>Model answer</strong></p>'):
   c['back']='<p><strong>Model answer</strong></p>'+c['back']
  if 'Common trap' not in c['back']:
   if i not in traps: quarantine.append((i,c));continue
   c['back']+='<p><strong>Common trap</strong></p><p>'+traps[i]+'</p>'
  kept.append(c)
 else: quarantine.append((i,c))
(r/'mark-reviewed.json').write_text(json.dumps(kept,indent=2,ensure_ascii=False)+'\n')
(r/'mark-review'/'quarantined.json').write_text(json.dumps([c for i,c in quarantine],indent=2,ensure_ascii=False)+'\n')
with (r/'mark-review'/'sources.tsv').open('w') as f:
 w=csv.writer(f,delimiter='\t');w.writerow(['stable_key','source','verified','verdict'])
 for i,c in enumerate(x):
  if i in verified and not any(j==i for j,_ in quarantine):u,n=verified[i];w.writerow([c['stable_key'],u,'yes','retained: '+n])
  else:
   source=(p1+'; '+p2+'; '+p3 if i<64 else s1+'; https://filestore.aqa.org.uk/resources/sociology/AQA-71922-SMS.PDF')
   note='quarantined: source search did not establish every substantive claim or a specific marking point'
   if i==42:note='quarantined: scenario does not establish perceived hostility needed for hostile attribution bias'
   if i in (86,87):note='quarantined: back refers to a specific past paper, contrary to brief'
   w.writerow([c['stable_key'],source,'no',note])
print('retained',len(kept),'quarantined',len(quarantine))
